const response = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Token exists and is not empty", function () {
    pm.expect(response.token).to.be.a("string");
    pm.expect(response.token.length).to.be.above(0);
});

if (pm.response.code === 200 &&
    typeof response.token === "string" &&
    response.token.length > 0) {
    pm.environment.set("token", response.token);
}
pm.test("Auth returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Auth response contains token", function () {
    const response = pm.response.json();

    pm.expect(response).to.have.property("token");
    pm.expect(response.token).to.be.a("string");
    pm.expect(response.token.length).to.be.above(0);
});

pm.test("Invalid credentials are rejected", function () {
    const response = pm.response.json();

    pm.expect(response.reason).to.eql("Bad credentials");
    pm.expect(response).to.not.have.property("token");
});

pm.test("Booking list returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Booking list is an array", function () {
    const bookings = pm.response.json();
    pm.expect(bookings).to.be.an("array");
});
pm.test("All bookings have valid IDs", function () {
    const bookings = pm.response.json();

    pm.expect(bookings.length).to.be.above(0);

    bookings.forEach(function (booking) {
        pm.expect(booking.bookingid).to.be.a("number");
        pm.expect(booking.bookingid).to.be.above(0);
    });
});
pm.test("Response time is below 3000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(3000);
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});
pm.test("Booking has firstname and lastname", function () {
    const booking = pm.response.json();

    pm.expect(booking).to.have.property("firstname");
    pm.expect(booking).to.have.property("lastname");

    pm.expect(booking.firstname).to.be.a("string");
    pm.expect(booking.lastname).to.be.a("string");
});
pm.test("Booking price and deposit types are valid", function () {
    const booking = pm.response.json();

    pm.expect(booking.totalprice).to.be.a("number");
    pm.expect(booking.depositpaid).to.be.a("boolean");
});
pm.test("Booking dates are valid strings", function () {
    const booking = pm.response.json();

    pm.expect(booking).to.have.property("bookingdates");
    pm.expect(booking.bookingdates.checkin).to.be.a("string");
    pm.expect(booking.bookingdates.checkout).to.be.a("string");
});
pm.test("Booking dates have valid format", function () {
    const dates = pm.response.json().bookingdates;
    const datePattern = /^\d{4}-\d{2}-\d{2}$/;

    pm.expect(dates.checkin).to.match(datePattern);
    pm.expect(dates.checkout).to.match(datePattern);
});
pm.test("Checkout date is not before checkin", function () {
    const dates = pm.response.json().bookingdates;

    const checkin = new Date(dates.checkin);
    const checkout = new Date(dates.checkout);

    pm.expect(checkin.getTime()).to.not.be.NaN;
    pm.expect(checkout.getTime()).to.not.be.NaN;
    pm.expect(checkout.getTime()).to.be.at.least(checkin.getTime());
});

pm.test("Invalid booking ID returns 404", function () {
    pm.response.to.have.status(404);
});

const response = pm.response.json();

pm.test("Booking created successfully", function () {
    pm.response.to.have.status(200);
    pm.expect(response.bookingid).to.be.a("number");
});

if (
    pm.response.code === 200 &&
