    pm.expect(dates.checkin).to.eql("2027-02-01");
    pm.expect(dates.checkout).to.eql("2027-02-05");
});
pm.test("Created booking has correct additional needs", function () {
    const booking = pm.response.json().booking;

    pm.expect(booking.additionalneeds).to.eql("Breakfast");
});

pm.test("Created booking can be retrieved", function () {
    pm.response.to.have.status(200);

    const booking = pm.response.json();

    pm.expect(booking.firstname).to.eql("Sara");
    pm.expect(booking.lastname).to.eql("Ahmed");
});
pm.test("Retrieved booking matches created data", function () {
    const booking = pm.response.json();

    pm.expect(booking.totalprice).to.eql(500);
    pm.expect(booking.depositpaid).to.eql(true);
    pm.expect(booking.bookingdates.checkin).to.eql("2027-02-01");
