pm.test("Updated booking can be retrieved", function () {
    pm.response.to.have.status(200);
});

pm.test("Retrieved booking has valid data", function () {
    const booking = pm.response.json();

    pm.expect(booking.firstname).to.be.a("string");
    pm.expect(booking.lastname).to.be.a("string");
    pm.expect(booking.totalprice).to.be.a("number");
});
pm.test("Updated booking contains new values", function () {
    const booking = pm.response.json();

    pm.expect(booking.firstname).to.eql("Mona");
    pm.expect(booking.totalprice).to.eql(800);
});

pm.test("Partial update returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("PATCH updates firstname and keeps other data", function (done) {
    const bookingId = pm.environment.get("bookingId");

    pm.sendRequest({
        url: pm.environment.get("baseUrl") + "/booking/" + bookingId,
        method: "GET"
    }, function (err, res) {
        try {
            pm.expect(err).to.be.null;
            pm.expect(res.code).to.eql(200);

            const booking = res.json();

            pm.expect(booking.firstname).to.eql("Nour");
            pm.expect(booking.lastname).to.eql("Ahmed");
            pm.expect(booking.totalprice).to.eql(500);
            pm.expect(booking.depositpaid).to.eql(true);

            done();
        } catch (error) {
            done(error);
        }
    });
});

pm.test("Delete booking returns 201", function () {
    pm.response.to.have.status(201);
});
pm.test("Deleted booking cannot be retrieved", function (done) {
    const bookingId = pm.environment.get("bookingId");

    pm.sendRequest({
        url: pm.environment.get("baseUrl") + "/booking/" + bookingId,
        method: "GET"
    }, function (err, res) {
        pm.expect(err).to.be.null;
        pm.expect(res.code).to.eql(404);
        done();
    });
});

pm.test("Response body is an array", function () {
    const response = pm.response.json();
    pm.expect(response).to.be.an("array");
});

pm.test("First booking has a numeric ID", function () {
    const bookings = pm.response.json();

    pm.expect(bookings.length).to.be.above(0);
    pm.expect(bookings[0]).to.have.property("bookingid");
    pm.expect(bookings[0].bookingid).to.be.a("number");
});
